window.setLanguage = function(lang) {
  currentLang = lang;
  localStorage.setItem("justChessLang", lang);
  i18next.changeLanguage(lang, () => {
    updateUI();
  });
};

window.changeLanguage = function(lang) {
  window.setLanguage(lang);
};
